if [[ -n "$ARGC_COMPLETIONS_ROOT" && -f "$ARGC_COMPLETIONS_ROOT/utils/_argc_utils.sh" ]]; then
    . "$ARGC_COMPLETIONS_ROOT/utils/_argc_utils.sh"
fi

_choice_apk() {
    _argc_util_comp_path exts=.apk,.apks
}

_choice_device() {
    adb devices 2>/dev/null | gawk 'NR > 1 && NF { print $1 "\t" $2 }'
}

_choice_host() {
    compgen -A hostname
    adb devices 2>/dev/null | gawk 'NR > 1 && NF && $1 ~ /:/ { print $1 }'
}

_choice_package() {
    _argc_util_cache 30 _choice_package_uncached
}

_choice_package_uncached() {
    adb shell pm list packages 2>/dev/null | sed -n 's/^package://p'
}

_choice_pull_remote() {
    _helper_remote_path
}

_choice_push_remote() {
    _helper_remote_path
}

_choice_socket_spec() {
    printf 'tcp:\0\n'
    printf 'localabstract:\0\n'
    printf 'localreserved:\0\n'
    printf 'localfilesystem:\0\n'
    printf 'dev:\0\n'
    printf 'jdwp:\0\n'
    printf 'vsock:\0\n'
    printf 'acceptfd:\0\n'
}

_choice_transport_id() {
    adb devices -l 2>/dev/null | gawk 'NR > 1 { for (i = 1; i <= NF; i++) if ($i ~ /^transport_id:/) { sub(/^transport_id:/, "", $i); print $i } }'
}

_helper_remote_path() {
    local path="${ARGC_CWORD:-}"
    local dir=.
    local entry
    local -a adb_cmd=(adb)

    if [[ "$path" == */* ]]; then
        dir="${path%/*}"
        [[ -z "$dir" ]] && dir=/
    fi
    [[ -n "${argc_s:-}" ]] && adb_cmd+=(-s "$argc_s")

    while IFS= read -r entry; do
        entry="${entry%$'\r'}"
        [[ -z "$entry" || "$entry" == . || "$entry" == .. ]] && continue
        if [[ "$dir" == . ]]; then
            printf '%s' "$entry"
        else
            printf '%s/%s' "${dir%/}" "$entry"
        fi
        [[ "$entry" == */ ]] && printf '\0'
        printf '\n'
    done < <("${adb_cmd[@]}" shell ls -a1p -- "$dir" 2>/dev/null)
}
# <<< CHOICES

command eval "$(argc --argc-eval "$0" "$@")"
